import{_ as e,a as r,b as a,c as n}from"./chunks/steam-board-connection.kmTJrBxh.js";import{_ as o,o as s,c as d,a0 as i}from"./chunks/framework.DZqO77tS.js";const C=JSON.parse('{"title":"EcoCONNECT technical notes","description":"","frontmatter":{},"headers":[],"relativePath":"en/docs/internal.md","filePath":"en/docs/internal.md"}'),c={name:"en/docs/internal.md"};function h(b,t,l,u,p,m){return s(),d("div",null,[...t[0]||(t[0]=[i('<h1 id="ecoconnect-technical-notes" tabindex="-1">EcoCONNECT technical notes <a class="header-anchor" href="#ecoconnect-technical-notes" aria-label="Permalink to &quot;EcoCONNECT technical notes&quot;">​</a></h1><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>EcoCONNECT is made of a main unit (the data processing part) and a STEAM sensor. It runs on three alkaline batteries or USB power, and it is an IoT device with several connector wires you can use freely.</p><p><img src="'+e+'" alt="summary"></p><h3 id="specifications" tabindex="-1">Specifications <a class="header-anchor" href="#specifications" aria-label="Permalink to &quot;Specifications&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Item</th><th>Value</th></tr></thead><tbody><tr><td>MPU</td><td>Raspberry Pi Pico 2</td></tr><tr><td>Data communication</td><td>LoRaWAN (A660-900T22)</td></tr><tr><td>Development language</td><td>MicroPython</td></tr><tr><td>Sensors</td><td>Temperature / humidity / pressure (BME280), illuminance (BH1750)</td></tr><tr><td>Power</td><td>Three alkaline batteries</td></tr></tbody></table><h2 id="structure" tabindex="-1">Structure <a class="header-anchor" href="#structure" aria-label="Permalink to &quot;Structure&quot;">​</a></h2><h3 id="main-unit-structure" tabindex="-1">Main unit structure <a class="header-anchor" href="#main-unit-structure" aria-label="Permalink to &quot;Main unit structure&quot;">​</a></h3><p>The main board processes data from each sensor device and sends that data. It is a four-layer board.</p><p>The MPU is a Raspberry Pi Pico 2, connected to the LoRaWAN module (A660-900T22) by serial communication.</p><p>It also talks to the sensors on the STEAM board over an I2C bus.</p><p>The LoRaWAN module (A660-900T22) can be fitted either as the module alone or as the evaluation module.</p><p>To check LoRaWAN behavior, mount the evaluation module on pin headers. Debugging is smoother that way.</p><p><a href="/AuraLinc-Community/pdf/Schematic-EcoCONNECT.pdf">Main unit schematic</a></p><h3 id="steam-sensor-structure" tabindex="-1">STEAM sensor structure <a class="header-anchor" href="#steam-sensor-structure" aria-label="Permalink to &quot;STEAM sensor structure&quot;">​</a></h3><p>This is a four-layer board with environmental sensors (temperature, humidity, ambient light, and pressure). Each sensor talks to the MPU on one I2C bus.</p><p>The sensors expected on the board are the BME280 and the BH1750 (see the table below). Mount the BME280 on the front of the board and the BH1750 on the back.</p><p>If you use a sensor module that is not in the list, change the I2C target address on the MPU side, and add the signal pins you need or connect them with cables.</p><p>Add pull-up resistors (R1 and R2) when neither of the sensor modules you use already includes them.</p><table tabindex="0"><thead><tr><th>Sensor</th><th>Module name</th><th>Part number</th></tr></thead><tbody><tr><td>Temperature, humidity, and pressure sensor module</td><td>Switch Science BME280 temperature, humidity, and pressure sensor module</td><td>SSCI-022361</td></tr><tr><td>Illuminance sensor module</td><td>GY-302 BH1750 light intensity module</td><td>GY-302 compatible</td></tr></tbody></table><p><a href="/AuraLinc-Community/pdf/sch-steam-board.pdf">STEAM sensor schematic</a></p><h2 id="connectors" tabindex="-1">Connectors <a class="header-anchor" href="#connectors" aria-label="Permalink to &quot;Connectors&quot;">​</a></h2><h3 id="connectors-and-pin-assignment-on-the-main-unit" tabindex="-1">Connectors and pin assignment on the main unit <a class="header-anchor" href="#connectors-and-pin-assignment-on-the-main-unit" aria-label="Permalink to &quot;Connectors and pin assignment on the main unit&quot;">​</a></h3><p>Role and pin assignment of each connector. When you use the STEAM board, connectors J1 and J2 are used.</p><p>Pins on the expansion connectors (J4 and J6) are free to use.</p><p>The firmware-update connector (J7) is used when updating the LoRaWAN module firmware.</p><p>Pins on the add-on board connectors (J5 and J8) are reserved for future expansion.</p><table tabindex="0"><thead><tr><th>Connector</th><th>Pin assignment</th><th>Use</th></tr></thead><tbody><tr><td>J1</td><td>1 : GND<br>2 : VBAT sens.<br>3 : VBAT<br>4 : Reserve</td><td>Connect to the battery</td></tr><tr><td>J2</td><td>1 : SCL<br>3 : SDA<br>5 : 3V3<br>2/4/6/7/8 : GND</td><td>Connect to the STEAM board</td></tr><tr><td>J4</td><td>1 : VBUS<br>2 : 3V3_EN<br>3 : 3V3<br>4 : ADC_VREF<br>5 : AGND<br>6 : GPIO19<br>7 : GPIO18<br>8 : GPIO17</td><td>Expansion connector<br>(connected to Raspberry Pi Pico pins)</td></tr><tr><td>J5/J8</td><td>1 : GPIO16<br>4 : VSYS<br>6 : J8 P4<br>7 : J8 P5<br>10 : J8 P1<br>2/3/5/8/9/11/12 : GND</td><td>For a planned add-on board</td></tr><tr><td>J6</td><td>1 : GPIO2<br>2 : GPIO4<br>3 : GPIO5<br>4 : GPIO6<br>5 : GPIO7<br>6 : GPIO8<br>7 : GPIO9<br>8 : GPIO10<br>9 : GPIO11<br>10 : GPIO12<br>11 : GPIO13<br>12 : GPIO15</td><td>Expansion connector<br>(connected to Raspberry Pi Pico pins)</td></tr><tr><td>J7</td><td>1 : VCC<br>2 : CTS<br>3 : SETB<br>4 : GND<br>5 : TXG<br>6 : XRES</td><td>Firmware update (A660-900T)</td></tr></tbody></table><p><img src="'+r+'" alt="main board"></p><h3 id="connectors-and-pin-assignment-on-the-steam-sensor" tabindex="-1">Connectors and pin assignment on the STEAM sensor <a class="header-anchor" href="#connectors-and-pin-assignment-on-the-steam-sensor" aria-label="Permalink to &quot;Connectors and pin assignment on the STEAM sensor&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Connector</th><th>Pin assignment</th><th>Use</th></tr></thead><tbody><tr><td>J1</td><td>1 : SDA<br>3 : SCL<br>5 : 3V3<br>2/4/6/7/8 : GND</td><td>Connect to the main board</td></tr><tr><td>J2</td><td>1 : ADDR<br>2 : SDA<br>3 : SCL<br>4 : GND<br>5 : 3V3</td><td>Connect to the BH1750<br>(back of the board)</td></tr><tr><td>J3</td><td>1 : SDO<br>2 : SCL<br>3 : SDA<br>4 : CSR<br>5 : GND<br>6 : Vcore<br>7 : VIO</td><td>Connect to the BME280<br>(front of the board)</td></tr></tbody></table><p><img src="'+a+'" alt="steam board"></p><h2 id="cable-wiring" tabindex="-1">Cable wiring <a class="header-anchor" href="#cable-wiring" aria-label="Permalink to &quot;Cable wiring&quot;">​</a></h2><p>EcoCONNECT (left) and the STEAM sensor (J1, right) are connected as shown below.</p><p>Keep the cable length to 30 cm or less.</p><p><img src="'+n+'" alt="steam board connection"></p>',36)])])}const S=o(c,[["render",h]]);export{C as __pageData,S as default};
